// SPDX-License-Identifier: MIT
// Security agent — Flags risky MCP grants, leaked secrets, dangerous diffs.

export const SYSTEM_PROMPT = `You scan the harness for the security regressions that matter: MCP grants that widened (Bash(rm:*), shell on, network on, file-write on), .env or token strings that escaped the redaction set, dependency updates that pulled in CVEs, and policy files that drifted from default-deny. Report each finding with a file:line, a severity (HIGH / MEDIUM), and the smallest fix. Never approve a change that widens a permission without a written reason in the PR description. You operate inside the agentic-devops-agent harness; defer destructive actions to the user.`;

export const NAME = 'security';
export const TIER = 'opus' as const;

import test from 'node:test';import assert from 'node:assert/strict';
import {Client} from '@modelcontextprotocol/client';import {StdioClientTransport} from '@modelcontextprotocol/client/stdio';import {fixture} from '../src/planner.mjs';
test('official SDK stdio discovers tools and executes plan validation rollback negatives',async()=>{
 const transport=new StdioClientTransport({command:process.execPath,args:['src/mcp.mjs'],env:{PATH:process.env.PATH},stderr:'pipe'});const client=new Client({name:'e2e',version:'1'});await client.connect(transport);
 try{const list=await client.listTools();assert.equal(list.tools.length,7);const call=async(name,input)=>client.callTool({name:'devops_'+name,arguments:{input}});const p=await call('plan',fixture);assert.equal(p.isError,false);const bundle=JSON.parse(p.content[0].text);assert.equal((await call('validate',bundle)).isError,false);assert.equal((await call('plan',{...fixture,command:'id'})).isError,true);assert.equal((await call('test',{})).isError,true);assert.equal((await client.readResource({uri:'ruv://agentic-devops/policy'})).contents.length,1)}finally{await client.close()}
});

{
  "servers": {
    "agentic-devops-agent": {
      "command": "node",
      "args": [
        ".harness/generated/bin/cli.js",
        "mcp"
      ]
    }
  }
}

// SPDX-License-Identifier: MIT
// Benchmarker agent — Runs the perf gates and reports regressions.

export const SYSTEM_PROMPT = `You run the project's declared benchmark suite (cargo bench, npm run bench, or whatever the manifest names) and compare against the baseline. Report regressions only when they cross the project's declared threshold — noise is worse than no result. Distinguish a real regression (statistically significant + reproducible) from a single-run flake. Write the result to memory so the maintainer can quote it. You operate inside the agentic-devops-agent harness; defer destructive actions to the user.`;

export const NAME = 'benchmarker';
export const TIER = 'sonnet' as const;
